-- Mage Style 1 Pyromancer replaces Mana Flow (Q 2026-10-17, artifact comment on the Mage Dossier).
-- cards.style_only: 'MG:1' = only in the deck under Pyromancer, '!MG:1' = every Style but Pyromancer.
-- 7 Pyro cards (MG-026..032) take the place of the 7 Mage cards with the lowest dmg per game in the sim (Claude pick, Q delegated).
alter table public.cards add column if not exists style_only text;
comment on column public.cards.style_only is '"MG:1" = only in the deck under that Style; "!MG:1" = under every Style but that one; null = always';

update public.champion_styles set name = 'Pyromancer', effect = 'Strike with a Skill card in your chain and 1 Mana left after paying: spend 1 Mana, opponent gains 1 Ignite (1% Max HP burn per stack each turn, heals −25%, 3 turns, max 4 stacks). Molten Shield: when you Block, spend up to 3 Mana for Shield 5 per Mana this turn; every hit your Block stops gives the attacker 1 Ignite.'
where champion_id = 'MG' and slot = 1;

update public.cards set style_only = '!MG:1' where id in ('MG-001', 'MG-018', 'MG-007', 'MG-008', 'MG-025', 'MG-021', 'MG-016');

insert into public.cards (id, champion_id, name, source, line, type, dmg, effect, copies, sort_order, in_deck, tags, effect_json, cost, style_only) values
  ('MG-026', 'MG', 'Blazing Catalyst', 'Q', 'Pyro', 'S', 6, 'Comes into play: Gain 2 resource / Before action, if you play Strike and opponent has 1+ Ignite stack: Every card in your chain +5 dmg per Ignite stack on opponent', 1, 26, true, '{Spell,Attack}', '[{"hook":"onDraw","do":[{"a":"gainRes","who":"self","n":2}]},{"hook":"modify","if":[{"c":"selfAction","a":"strike"},{"c":"ignite","who":"enemy","op":">=","n":1}],"do":[{"a":"addDmg","target":"chain","n":5,"per":"enemyIgnite"}]}]'::jsonb, 1, 'MG:1'),
  ('MG-027', 'MG', 'Infernal Conflagration', 'Q', 'Pyro', 'S', 16, 'Before action, if you play Strike and opponent has 3+ Ignite stacks: This card dmg 150%, opponent''s Ignite explodes: all its remaining burn dmg at once', 1, 27, true, '{Spell,Attack}', '[{"hook":"modify","if":[{"c":"selfAction","a":"strike"},{"c":"ignite","who":"enemy","op":">=","n":3}],"do":[{"a":"mulDmg","target":"this","pct":150},{"a":"consumeIgnite","who":"enemy"}]}]'::jsonb, 5, 'MG:1'),
  ('MG-028', 'MG', 'Wildfire Command', 'Q', 'Pyro', 'S', 7, 'After action, if you play Strike and this card hits clean and opponent has 1+ Ignite stack: Opponent discards their card in this slot from the Field to the bottom of their deck (Cut) / After action, if you play Strike and this card hits clean and opponent has no Ignite: Opponent discards their 2 oldest cards from the Field to the bottom of their deck (Cut)', 1, 28, true, '{Spell,Control}', '[{"hook":"onResolve","if":[{"c":"selfAction","a":"strike"},{"c":"hitResult","r":"clean"},{"c":"ignite","who":"enemy","op":">=","n":1}],"do":[{"a":"cut","which":"facing","n":1}]},{"hook":"onResolve","if":[{"c":"selfAction","a":"strike"},{"c":"hitResult","r":"clean"},{"c":"ignite","who":"enemy","op":"<","n":1}],"do":[{"a":"cut","which":"oldest","n":2}]}]'::jsonb, 2, 'MG:1'),
  ('MG-029', 'MG', 'Sear Flesh', 'Q', 'Pyro', 'S', 8, 'After action, if you play Strike and this card hits clean: Opponent can''t Block next turn, opponent''s Ignite starts its 3 turns again', 1, 29, true, '{Spell,Control}', '[{"hook":"onResolve","if":[{"c":"selfAction","a":"strike"},{"c":"hitResult","r":"clean"}],"do":[{"a":"status","who":"enemy","kind":"noBlock","turns":1},{"a":"ignite","who":"enemy","n":0}]}]'::jsonb, 2, 'MG:1'),
  ('MG-030', 'MG', 'Heatstroke', 'Q', 'Pyro', 'S', 7, 'After action, if you play Strike and this card hits clean: Opponent can''t Strike next turn / After action, if you play Strike and opponent has 1+ Ignite stack: Gain 1 resource', 1, 30, true, '{Spell,Control}', '[{"hook":"onResolve","if":[{"c":"selfAction","a":"strike"},{"c":"hitResult","r":"clean"}],"do":[{"a":"status","who":"enemy","kind":"noStrike","turns":1}]},{"hook":"onResolve","if":[{"c":"selfAction","a":"strike"},{"c":"ignite","who":"enemy","op":">=","n":1}],"do":[{"a":"gainRes","who":"self","n":1}]}]'::jsonb, 3, 'MG:1'),
  ('MG-031', 'MG', 'Ash to Ash', 'Q', 'Pyro', 'S', 5, 'After action, if you play Strike and this card hits clean: Opponent gains 1 Ignite per Skill in your chain (1% Max HP burn per stack each turn, heals −25%, 3 turns, max 4)', 1, 31, true, '{Spell,Attack}', '[{"hook":"onResolve","if":[{"c":"selfAction","a":"strike"},{"c":"hitResult","r":"clean"}],"do":[{"a":"ignite","who":"enemy","n":1,"per":"chainS"}]}]'::jsonb, 1, 'MG:1'),
  ('MG-032', 'MG', 'Magma Trap', 'Q', 'Pyro', 'S', 6, 'Every turn (Hold), if opponent plays Charge: Opponent lose 5 HP, opponent gains 1 Ignite (1% Max HP burn per stack each turn, heals −25%, 3 turns, max 4)', 1, 32, true, '{Spell,Hold,Control}', '[{"hook":"onHeld","if":[{"c":"enemyAction","a":"charge"}],"do":[{"a":"loseHp","who":"enemy","n":5},{"a":"ignite","who":"enemy","n":1}]}]'::jsonb, 0, 'MG:1')
on conflict (id) do update set name = excluded.name, dmg = excluded.dmg, effect = excluded.effect, effect_json = excluded.effect_json, cost = excluded.cost, style_only = excluded.style_only, in_deck = excluded.in_deck, tags = excluded.tags;
